package net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.SmtpOutboundConfig;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.valueobject.UseTlsVO;

class UseTlsValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of use tls of smtp outbound config")
  void test_use_tls_value_holder_assign_plain_value() {
    Object holder = new Object();
    UseTlsValueHolder<Object> value = new UseTlsValueHolder<>(holder);
    Assertions.assertSame(holder, value.useTls(true), "Setters must return the holder");
    Assertions.assertTrue(value.getUseTlsValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(true, value.getUseTls().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of use tls of smtp outbound config")
  void test_use_tls_value_holder_assign_value_object() {
    Object holder = new Object();
    UseTlsValueHolder<Object> value = new UseTlsValueHolder<>(holder);
    UseTlsVO vo = UseTlsVO.from(true);
    Assertions.assertFalse(value.getUseTlsValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.useTls(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getUseTlsValue().orElseThrow());
    Assertions.assertSame(holder, value.useTls(Optional.empty()));
    Assertions.assertFalse(value.getUseTlsValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.useTls(Optional.of(vo)));
    Assertions.assertSame(vo, value.getUseTlsValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of use tls of smtp outbound config against the original")
  void test_use_tls_value_holder_read() {
    Object holder = new Object();
    UseTlsValueHolder<Object> value = new UseTlsValueHolder<>(holder);
    UseTlsVO vo = UseTlsVO.from(true);
    UseTlsVO other = UseTlsVO.from(true);
    SmtpOutboundConfig original = Mockito.mock(SmtpOutboundConfig.class);
    Mockito.when(original.getUseTlsValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readUseTls(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readUseTls(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.useTls(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readUseTls(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readUseTls(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of use tls of smtp outbound config")
  void test_use_tls_value_holder_unset() {
    Object holder = new Object();
    UseTlsValueHolder<Object> value = new UseTlsValueHolder<>(holder);
    UseTlsVO vo = UseTlsVO.from(true);
    value.useTls(vo);
    Assertions.assertSame(holder, value.unsetUseTlsIfMatches("useTls_other"));
    Assertions.assertTrue(value.getUseTlsValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetUseTlsIfMatches("useTls"));
    Assertions.assertFalse(value.getUseTlsValue().isPresent(),
        "The field name must clear the value");
    value.useTls(vo);
    Assertions.assertSame(holder, value.unsetUseTls());
    Assertions.assertFalse(value.getUseTlsValue().isPresent(), "Unset must clear the value");
  }
}
